<div class="admin-panel jobcard-list-panel"><div class="jobcard-list-heading"><h2><?= e($title) ?> (<?= count($rows) ?>)</h2></div><div class="table-responsive"><table class="table admin-table jobcard-table"><thead><tr><th>Job Card No.</th><th>Vehicle Details</th><th>Customer Details</th><th>Job Summary</th><th>Priority</th><th>Created On</th><th>Actions</th></tr></thead><tbody><?php if (!$rows): ?><tr><td colspan="7" class="empty-table">No <?= e(strtolower($status)) ?> job cards found.</td></tr><?php else: ?><?php foreach ($rows as $row): ?><tr><td><strong class="jobcard-number"><?= e($row['job_card_no']) ?></strong><span class="status-badge status-<?= e($row['status']) ?>"><?= e(strtoupper($row['status'])) ?></span><small><?= e($row['bay']) ?></small></td><td><strong><?= e($row['vehicle_number']) ?></strong><span><?= e($row['vehicle_type']) ?> · <?= e(trim(($row['make'] ?? '') . ' ' . $row['model'])) ?></span><small><?= e($row['current_mileage'] !== null ? number_format((float) $row['current_mileage'], 0) . ' KM' : '-') ?></small></td><td><strong><?= e($row['customer_name']) ?></strong><span><?= e($row['contact_number']) ?></span></td><td><?= e($row['complaint'] ?: $row['requested_work'] ?: 'No summary entered') ?></td><td><span class="priority-<?= e($row['priority']) ?>">● <?= e(ucfirst($row['priority'])) ?></span></td><td><?= e(date('d M Y', strtotime($row['created_at']))) ?><small><?= e(date('h:i A', strtotime($row['created_at']))) ?></small></td><td><div class="jobcard-actions"><a class="vehicle-action" href="#" title="View">◉</a><a class="vehicle-action" href="#" title="Edit">✎</a></div></td></tr><?php endforeach; ?><?php endif; ?></tbody></table></div></div>
